posts.body:
I didn't test it but try removing the message busy conditional in the plugin code (the thing I put a line over):
Sprite_Picture.prototype.isClickEnabled = function() {
var pic = this.picture();
return !!(pic && pic._commonEventId > 0 [S]&& !$gameMessage.isBusy()[/S]);
};
And then I checked the script call list and it says that:
// Anywhere: end the current non-Parallel map event
$gameMap._interpreter.command115();
So try adding to the plugin code that line:
Sprite_Picture.prototype.onClick = function() {
var pic = this.picture();
if (pic && pic._commonEventId > 0) {
$gameMap._interpreter.command115();
// prevent map touch-move + click-through
if ($gameTemp && $gameTemp.clearDestination) $gameTemp.clearDestination();
if (TouchInput && TouchInput.clear) TouchInput.clear();
$gameTemp.reserveCommonEvent(pic._commonEventId);
}
};
EDIT: Seems like the strike-through line didn't appear in the code, but it's that thing between the S and /S in brackets

